using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using Jellyfin.Database.Implementations;
using Jellyfin.Database.Implementations.Locking;
using Jellyfin.Database.Providers.Sqlite;
using Jellyfin.Database.Providers.Sqlite.CompiledModel;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.Extensions.Logging.Abstractions;
using Xunit;

namespace Jellyfin.Server.Implementations.Tests.Persistence;

public class CompiledModelTests
{
    /// <summary>
    /// The SQLite provider runs on the model generated by "dotnet ef dbcontext optimize". A change to an
    /// entity or its configuration without regenerating that model would silently run against a stale
    /// shape, so the generated model has to describe the same tables, columns, keys, indexes and foreign
    /// keys as the one the context builds from its configuration.
    /// </summary>
    [Fact]
    public void CompiledModel_MatchesModelBuiltFromConfiguration()
    {
        using var fromConfiguration = CreateContext(useCompiledModel: false);
        using var fromCompiledModel = CreateContext(useCompiledModel: true);

        Assert.Equal(Describe(fromConfiguration.Model), Describe(fromCompiledModel.Model));
    }

    private static JellyfinDbContext CreateContext(bool useCompiledModel)
    {
        var optionsBuilder = new DbContextOptionsBuilder<JellyfinDbContext>()
            .UseSqlite("Data Source=:memory:");
        if (useCompiledModel)
        {
            optionsBuilder.UseModel(JellyfinDbContextModel.Instance);
        }

        return new JellyfinDbContext(
            optionsBuilder.Options,
            NullLogger<JellyfinDbContext>.Instance,
            new SqliteDatabaseProvider(null!, NullLogger<SqliteDatabaseProvider>.Instance),
            new NoLockBehavior(NullLogger<NoLockBehavior>.Instance));
    }

    // Only facts that both a runtime model and a compiled model expose, so the two are comparable.
    private static List<string> Describe(IModel model)
    {
        var lines = new List<string>();
        foreach (var entityType in model.GetEntityTypes())
        {
            var table = entityType.GetTableName() ?? entityType.GetViewName() ?? "(none)";
            lines.Add($"entity {entityType.Name} table={table} query-filters={entityType.GetDeclaredQueryFilters().Count}");

            foreach (var property in entityType.GetProperties())
            {
                lines.Add(string.Create(
                    CultureInfo.InvariantCulture,
                    $"  property {entityType.Name}.{property.Name} column={property.GetColumnName()} type={property.ClrType} nullable={property.IsNullable} store-type={property.GetColumnType()} generated={property.ValueGenerated} concurrency={property.IsConcurrencyToken} max-length={property.GetMaxLength()}"));
            }

            foreach (var key in entityType.GetKeys())
            {
                lines.Add($"  key {entityType.Name} primary={key.IsPrimaryKey()} [{string.Join(",", key.Properties.Select(p => p.Name))}]");
            }

            foreach (var index in entityType.GetIndexes())
            {
                lines.Add($"  index {entityType.Name} name={index.GetDatabaseName()} unique={index.IsUnique} [{string.Join(",", index.Properties.Select(p => p.Name))}] filter={index.GetFilter()}");
            }

            foreach (var foreignKey in entityType.GetForeignKeys())
            {
                lines.Add($"  fk {entityType.Name} [{string.Join(",", foreignKey.Properties.Select(p => p.Name))}] -> {foreignKey.PrincipalEntityType.Name} [{string.Join(",", foreignKey.PrincipalKey.Properties.Select(p => p.Name))}] delete={foreignKey.DeleteBehavior} required={foreignKey.IsRequired} unique={foreignKey.IsUnique}");
            }

            foreach (var navigation in entityType.GetNavigations())
            {
                lines.Add($"  navigation {entityType.Name}.{navigation.Name} -> {navigation.TargetEntityType.Name} collection={navigation.IsCollection}");
            }
        }

        lines.Sort(System.StringComparer.Ordinal);
        return lines;
    }
}
